 (268898,"prayer (tephillah)","action","the psalmist","pray","to God",GOD,"paired with the cry","v1: 'Hear my PRAYER (tephillah), O LORD' - the petition begging God's ear."),
 (268900,"cry (shava)","action","the psalmist","cry for help","to God",GOD,"paired with the prayer","v1: 'let my CRY (shava) come to you!' - the loud plea reaching for God."),
 (268978,"call (qara)","action","the psalmist","call","to God in distress",GOD,"paired with the plea for a speedy answer","v2: 'in the day when I CALL (qara), answer me speedily!' - the urgent calling in the day of distress."),
 (269024,"pass away (kalah)","state","the psalmist","have his days pass away","like smoke",IB,"paired with the burning bones","v3: 'For my days PASS AWAY (kalah) like smoke' - the vanishing of life, days dissolving like smoke in the affliction."),
 (302589,"heart (leb)","faculty","the psalmist","be struck down and withered","like grass",IB,"paired with forgetting to eat","v4: 'My HEART (leb) is struck down like grass and has withered' - the inner self blighted by grief, the heart dried up."),
 (302592,"withered (yabesh)","state","the psalmist","be withered","in heart",IB,"paired with the struck-down heart","v4: 'like grass and has WITHERED (yabesh)' - the drying-up of the heart, vitality gone in the affliction."),
