 (268928,"pity (chanan)","disposition","God's servants","have pity / affection","for Zion's dust",IB,"paired with holding her stones dear","v14: 'and have PITY (chanan) on her dust' - the tender regard of the servants for ruined Zion, love for her very dust."),
 (268931,"fear (yare)","disposition","the nations","fear","the name of the LORD",GOD,"paired with the kings fearing his glory","v15: 'Nations will FEAR (yare) the name of the LORD' - the reverence the rebuilt Zion draws from the nations, awe of God's name."),
 (307203,"prayer (tephillah)","action","the destitute","pray","to God",GOD,"paired with God regarding it","v17: 'He regards the PRAYER (tephillah) of the destitute' - the prayer of the stripped-bare, which God does not overlook."),
