 (307208,"prayer (tephillah)","action","the destitute","pray","not despised by God",GOD,"paired with the destitute","v17: 'and does not despise their PRAYER (tephillah)' - the prayer of the poor that God will not scorn."),
 (268952,"praise (halal)","action","a people yet to be created","praise","the LORD",GOD,"paired with the recorded testimony","v18: 'so that a people yet to be created may PRAISE (halal) the LORD' - the praise of generations to come, worship recorded for the future."),
